function i(t,r="ج.م"){return typeof t!="number"||isNaN(t)?`0.00 ${r}`:`${(t/100).toFixed(2)} ${r}`}function s(t){return Math.round(t*100)}function o(t){try{const r=new Date(t);if(isNaN(r.getTime()))return"-";const e=String(r.getDate()).padStart(2,"0"),n=String(r.getMonth()+1).padStart(2,"0"),a=r.getFullYear();return`${e}/${n}/${a}`}catch{return"-"}}function u(t){try{const r=new Date(t);if(isNaN(r.getTime()))return"-";let e=r.getHours();const n=String(r.getMinutes()).padStart(2,"0"),a=e>=12?"م":"ص";return e=e%12,e=e||12,`${e}:${n} ${a}`}catch{return"-"}}function c(t){return`${o(t)} - ${u(t)}`}export{c as a,i as f,s as t};
